//U08FSCMFUKG-Ethan,U08FZAE7CRL-Bobby,U08GRCSU325-Tacy
const allow_users = ["U08FSCMFUKG", "U08FZAE7CRL","U08GRCSU325"];
let subtype = $json.subtype || 'NA';
let user_id = $json.user;
// Check if exists
const exists = allow_users.includes(user_id);

if ($json.bot_id || subtype === 'message_deleted' || subtype === 'message_changed' || !exists) {
  // Message came from a bot (including this one) → stop workflow
  return [];
} else {
  return [
    { 
      json: { 
        channel: $json.channel, 
        user: user_id,
        message_ts: $json.ts || 0,
        text: $json.text 
      }
    }
  ];
}

