// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let result = $json.output;
let message;
let data;
let action_encode;
let channel;
let message_ts;

try {
  //result = result.repalce('``','').replace('json\n', '')
  //var JS_result = JSON.parse(result);
  message = result.message;
  message_ts = result.message_ts || 0;
  data = result.data;
  action_encode = Buffer.from(JSON.stringify(data)).toString("base64");
  channel = result.channel;
}
catch (e) {
  message = result.message;
  channel = result.channel || "";
}

return [{ 
  json: {
    channel:channel,
    message: message, 
    message_ts: message_ts, 
    data: data, 
    action_encode: action_encode 
}}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
var payload = JSON.parse($json.body["payload"]);
var actions = payload.actions || [];
var check_button = false;
var action_name;
let action_encoded;
var action_decode;
//var "message_ts": "1759804099.061949",
var open_message_ts = 0;
var open_encode;
var approve_encode;
var process_encode, product_encode;
var selENV = 'LOCAL';

var callback_id = payload.callback_id || "";
var type_submit = payload.type || 'NA';
if (callback_id === 'approve_modal' || type_submit === 'view_submission') {
  check_button = true;
  action_name = type_submit === 'view_submission' ? 'process' : 'approve';
  product_encode = payload.private_metadata;
}
else {
  actions.forEach(s => {
    if (s.type === 'button'){
      check_button = true;
      action_name = s.value.split("_")[0];
      if (action_name === 'open') {
        action_encoded = s.value.split("_")[2];
      } else {
        action_encoded = s.action_id;
      }
      if (action_name === 'process') {
        product_encode = s.value.split("_")[1];
        const product_decode = JSON.parse(Buffer.from(product_encode, "base64").toString("utf8"));
        selENV = product_decode.evn || 'NA';
      }
      return 1;
    }
  });
}
// open config form
if (action_name === 'open') {
  open_message_ts = payload.container.message_ts;
  action_decode = JSON.parse(Buffer.from(action_encoded, "base64").toString("utf8"));
  open_encode = Buffer.from(JSON.stringify({open_message_ts: open_message_ts})).toString("base64");
}

// close config form
if (action_name === 'close') {
  open_message_ts = payload.container.message_ts;
}

// submit form
if (action_name === 'approve') {
  open_message_ts = payload.container.message_ts;
  // parser form state
  action_state = payload.state;
  approve_encode = Buffer.from(JSON.stringify({open_message_ts: open_message_ts})).toString("base64");
}

if (action_name === 'process') {
  open_message_ts = payload.container.message_ts;
  // parser form state
  action_state = {};
  process_encode = Buffer.from(JSON.stringify({open_message_ts: open_message_ts})).toString("base64");
}

//Buffer.from(JSON.stringify(data)).toString("base64")

return [{ json: { 
    payload: payload, 
    action_button:  check_button, 
    action_name: action_name, 
    action_decode: action_decode,
    open_encode: open_encode,
    approve_encode: approve_encode,
    process_encode: process_encode,
    product_encode: product_encode,
    ENV: selENV
  }}];

