  "model": sel_model.value || "",
  "evn": sel_evn.value || "",
  "product_type": sel_ptype.value || "",
  "product_setting": sel_psetting.value || "0_0",
  "product_id": data.product_block.product_input.value || 0,
  "product_name": data.pname_block.pname_input.value || "",
  "product_code": data.pcode_block.pcode_input.value || "",
  "sport_id": data.sport_block.sport_input.value || 0,
  "sport_name": data.sname_block.sname_input.value || "",
  "bettype_from": sel_bettype.split("-")[0] || 0,
  "bettype_to": sel_bettype.split("-")[1] || 0,
  "bettype_prize": data.btprize_block.btprize_input.value || 0,
  "bettype_contribution": data.btcontribution_block.btcontribution_ipput.value || 0
};

