   || product.evn === ''
   || product.product_type === ''
   || product.product_id === 0 
   || product.product_name === ''
   || product.sport_id === 0
   || product.sport_name === ''
   || product.bettype_from === 0
   || product.bettype_to === 0
   || product.bettype_from >= product.bettype_to) {
  is_valid = false;
  err_msg = product.product_type + ' Casino product info(s) are invalid.';
}

// check product setting type
