  err_msg = product.product_type + ' Casino product setting type is invalid.';
}

if (product.product_type === 'Live' && product.product_setting == '0_0') {
  is_valid = false;
  err_msg = product.product_type + ' Casino product setting type is invalid.';
}

var block_encode;
