var product_encode, product_decode;

actions.forEach(s => {
  chk_name = s.value.split("_")[0];
  if (s.type === 'button' 
      && (chk_name === 'approve' 
          || chk_name === 'process' 
          || chk_name === 'stop')){
    action_name = chk_name;
    action_encode = s.action_id;
    if (action_name === 'stop') {
      product_encode = s.value.split("_")[1];
    }
    return 1;
  }
});

// show input form
if (action_name === 'approve') {
  // close previous config message
  action_decode = JSON.parse(Buffer.from(action_encode.split('_')[1], "base64").toString("utf8"));
  message_ts = action_decode.open_message_ts;
}

if (action_name === 'process') {
  // close previous submit form
  action_decode = JSON.parse(Buffer.from(action_encode.split('_')[1], "base64").toString("utf8"));
  message_ts = action_decode.open_message_ts;
}

// InProgress
if (action_name === 'stop') {
  // close previous process confirmation
  action_decode = JSON.parse(Buffer.from(action_encode.split('_')[1], "base64").toString("utf8"));
  message_ts = action_decode.open_message_ts;
  product_decode = JSON.parse(Buffer.from(product_encode, "base64").toString("utf8"));
}

return [
  {
    json: {
      "payload": {
        "container": {
          channel_id: $json.channel,
          message_ts: message_ts,
          action_name: action_name,
          product_decode: product_decode
        }
      }
    }
  }
]

